sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Colorectal' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+MEKi';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Colorectal' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+MEKi'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_meki_agents(source_value) AS "meki_agents"
FROM base;
